// The fixture's registry script, a generation step (runic.json): writes
// src/__registry__/index.js in the format of the shadcn-svelte site's
// scripts/build-registry.ts (`Index[name].files`), for the examples of
// src/lib/registry/examples. The site's mdsx configuration reads it to put
// each preview's source below the preview.
import fs from 'node:fs';
import path from 'node:path';

const names = fs
  .readdirSync('src/lib/registry/examples')
  .filter(f => f.endsWith('.svelte'))
  .map(f => f.slice(0, -'.svelte'.length))
  .sort();

let index = `
// This file is autogenerated by scripts/build-registry.mjs
// Do not edit this file directly.
export const Index = {`;
for (const name of names)
  index += `
"${name}": {
	files: ["../lib/registry/examples/${name}.svelte"],
},`;
index += `
}
`;

fs.mkdirSync(path.join('src', '__registry__'), { recursive: true });
fs.writeFileSync(path.join('src', '__registry__', 'index.js'), index);
